WHITE = (255, 255, 255)
RED = (255, 0, 0)

# Set up the display
screen = pygame.display.set_mode((WIDTH, HEIGHT))

class Vehicle:
    def __init__(self):
        self.speed = 0
        self.acceleration = 0.1
        self.braking = -0.1

    def update(self):
        keys = pygame.key.get_pressed()
        if keys[pygame.K_UP]:
            self.speed += self.acceleration
        elif keys[pygame.K_DOWN]:
            self.speed += self.braking
        if self.speed > 100:
            self.speed = 100

class AIPlayer(Vehicle):
