        super().update()
        if self.speed < 50:
            self.speed += 0.5

class SpeedBoost:
    def __init__(self):
        self.threshold = 50
        self.boost = 20

    def activate(self, vehicle):
        if vehicle.speed >= self.threshold:
            vehicle.speed += self.boost

class PowerUp:
    def __init__(self):
        self.type = random.choice(["shield", "boost", "speed"])

    def apply(self, vehicle):
        if self.type == "shield":
            vehicle.speed = 100
        elif self.type == "boost":
            vehicle.speed += 20
        elif self.type == "speed":
            vehicle.speed = 50

class GameMode:
    def __init__(self, name, duration):
        self.name = name
        self.duration = duration

class GameModeManager:
